-- IDs fixos: reexecutar não duplica nem sobrescreve registros existentes.
-- Capítulo 3: Introdução a classes, objetos, métodos e strings — 20 questões.
BEGIN;
SET LOCAL standard_conforming_strings = on;

INSERT INTO public.questions (
  id, year, question_type, subject, exam, question_number, topic, difficulty,
  statement, options, correct_option, explanation, source, is_annulled, is_published
) VALUES
('1a28fe2e-ba56-529f-bc79-c4f1d15d035b', NULL, 'bibliography', 'Informática', 'CP-T', 1, 'Linguagem de Programação', 'Fácil', 'Declarar um campo private busca principalmente:', '["Transformá-lo em constante.","Torná-lo global.","Impedir qualquer uso por métodos da classe.","Controlar o acesso direto ao estado.","Criar cópias automáticas."]'::jsonb, 3, 'Métodos da própria classe podem ler e modificar o campo.', 'DEITEL, Paul; DEITEL, Harvey. Java: como programar. Tradução da 10ª edição norte-americana. Pearson Education do Brasil, 2017. Capítulo 3, seção 3.2, páginas 91–98 do PDF fornecido. Contexto: Java SE 8. Questão original de estudo; não é questão oficial do CP-T.', false, false),
('bf1777e2-fb5c-5fde-838e-289067c3152d', NULL, 'bibliography', 'Informática', 'CP-T', 2, 'Linguagem de Programação', 'Fácil', 'Um setter pode validar uma entrada antes de:', '["Atualizar o estado do objeto.","Alterar a sintaxe Java.","Apagar a classe.","Compilar a JVM.","Criar um pacote."]'::jsonb, 0, 'A validação preserva regras do objeto por uma interface controlada.', 'DEITEL, Paul; DEITEL, Harvey. Java: como programar. Tradução da 10ª edição norte-americana. Pearson Education do Brasil, 2017. Capítulo 3, seção 3.2, páginas 91–98 do PDF fornecido. Contexto: Java SE 8. Questão original de estudo; não é questão oficial do CP-T.', false, false),
('53d4e310-fad4-5ecf-a1dc-b37aeeebf02b', NULL, 'bibliography', 'Informática', 'CP-T', 3, 'Linguagem de Programação', 'Fácil', 'Um getter convencional tem como finalidade:', '["Fornecer acesso a uma informação do objeto.","Criar sempre outra instância.","Encerrar a JVM.","Compilar um arquivo.","Garantir alteração de todos os campos."]'::jsonb, 0, 'O acesso pode ser controlado sem expor diretamente o campo.', 'DEITEL, Paul; DEITEL, Harvey. Java: como programar. Tradução da 10ª edição norte-americana. Pearson Education do Brasil, 2017. Capítulo 3, seção 3.2, páginas 91–98 do PDF fornecido. Contexto: Java SE 8. Questão original de estudo; não é questão oficial do CP-T.', false, false),
('57edbc42-7f73-5631-b83b-4b0d33398d5f', NULL, 'bibliography', 'Informática', 'CP-T', 4, 'Linguagem de Programação', 'Fácil', 'Dois objetos da mesma classe têm campos de instância:', '["Sempre estáticos.","Sem valor possível.","Necessariamente compartilhados.","Separados para cada objeto.","Sempre constantes."]'::jsonb, 3, 'Uma alteração em uma instância não altera automaticamente outra.', 'DEITEL, Paul; DEITEL, Harvey. Java: como programar. Tradução da 10ª edição norte-americana. Pearson Education do Brasil, 2017. Capítulo 3, seção 3.2, páginas 91–98 do PDF fornecido. Contexto: Java SE 8. Questão original de estudo; não é questão oficial do CP-T.', false, false),
('abb232a2-e87b-50ea-937a-edd215507511', NULL, 'bibliography', 'Informática', 'CP-T', 5, 'Linguagem de Programação', 'Fácil', 'Qual é um tipo primitivo Java?', '["String.","int.","Integer.","Object.","Scanner."]'::jsonb, 1, 'Integer é a classe empacotadora correspondente a int.', 'DEITEL, Paul; DEITEL, Harvey. Java: como programar. Tradução da 10ª edição norte-americana. Pearson Education do Brasil, 2017. Capítulo 3, seção 3.3, páginas 99–100 do PDF fornecido. Contexto: Java SE 8. Questão original de estudo; não é questão oficial do CP-T.', false, false),
('82c06022-86cb-5a42-bfcd-fd233a421b33', NULL, 'bibliography', 'Informática', 'CP-T', 6, 'Linguagem de Programação', 'Fácil', 'Uma variável String armazena conceitualmente:', '["Uma referência a objeto, ou null.","Um primitivo textual.","Um método.","Uma classe inteira por cópia.","Uma instrução import."]'::jsonb, 0, 'String é um tipo por referência.', 'DEITEL, Paul; DEITEL, Harvey. Java: como programar. Tradução da 10ª edição norte-americana. Pearson Education do Brasil, 2017. Capítulo 3, seção 3.3, páginas 99–100 do PDF fornecido. Contexto: Java SE 8. Questão original de estudo; não é questão oficial do CP-T.', false, false),
('6d9621ef-52db-5158-be99-1cebaace7d07', NULL, 'bibliography', 'Informática', 'CP-T', 7, 'Linguagem de Programação', 'Fácil', 'Qual valor inicial padrão de um campo int de instância?', '["null.","-1.","0.","Indefinido.","1."]'::jsonb, 2, 'Campos recebem valores padrão quando o objeto é inicializado.', 'DEITEL, Paul; DEITEL, Harvey. Java: como programar. Tradução da 10ª edição norte-americana. Pearson Education do Brasil, 2017. Capítulo 3, seção 3.3, páginas 99–100 do PDF fornecido. Contexto: Java SE 8. Questão original de estudo; não é questão oficial do CP-T.', false, false),
('c074f6ee-871f-5fba-95e1-a3e19358401e', NULL, 'bibliography', 'Informática', 'CP-T', 8, 'Linguagem de Programação', 'Fácil', 'Qual valor inicial padrão de um campo de referência?', '["Um objeto criado automaticamente.","Uma string vazia obrigatória.","false.","0 como int.","null."]'::jsonb, 4, 'null indica ausência de referência a objeto.', 'DEITEL, Paul; DEITEL, Harvey. Java: como programar. Tradução da 10ª edição norte-americana. Pearson Education do Brasil, 2017. Capítulo 3, seção 3.3, páginas 99–100 do PDF fornecido. Contexto: Java SE 8. Questão original de estudo; não é questão oficial do CP-T.', false, false),
('e5769f4c-b4d7-506d-948c-ccf299695bb4', NULL, 'bibliography', 'Informática', 'CP-T', 9, 'Linguagem de Programação', 'Fácil', 'Uma variável local int pode ser lida sem inicialização definida?', '["Somente em main.","Não; o compilador exige atribuição definida.","Sim, recebe null.","Sim, recebe sempre zero.","Somente quando public."]'::jsonb, 1, 'Valores padrão de campos não se aplicam da mesma maneira a locais.', 'DEITEL, Paul; DEITEL, Harvey. Java: como programar. Tradução da 10ª edição norte-americana. Pearson Education do Brasil, 2017. Capítulo 3, seção 3.3, páginas 99–100 do PDF fornecido. Contexto: Java SE 8. Questão original de estudo; não é questão oficial do CP-T.', false, false),
('2ce2499a-6833-5e54-a56f-f64a581e2b5e', NULL, 'bibliography', 'Informática', 'CP-T', 10, 'Linguagem de Programação', 'Fácil', 'O nome de um construtor deve ser:', '["Qualquer nome com void.","Sempre main.","Igual ao pacote.","Igual ao nome da classe.","Sempre init."]'::jsonb, 3, 'Construtores não declaram tipo de retorno.', 'DEITEL, Paul; DEITEL, Harvey. Java: como programar. Tradução da 10ª edição norte-americana. Pearson Education do Brasil, 2017. Capítulo 3, seção 3.4, páginas 99–100 do PDF fornecido. Contexto: Java SE 8. Questão original de estudo; não é questão oficial do CP-T.', false, false),
('1266b39f-3b79-57e7-b8d5-8e3d5a03c114', NULL, 'bibliography', 'Informática', 'CP-T', 11, 'Linguagem de Programação', 'Fácil', '`void Produto()` dentro de Produto declara:', '["Uma interface.","Um método, não um construtor.","Uma classe abstrata.","Um campo.","Um construtor válido."]'::jsonb, 1, 'Declarar void muda a construção para um método comum.', 'DEITEL, Paul; DEITEL, Harvey. Java: como programar. Tradução da 10ª edição norte-americana. Pearson Education do Brasil, 2017. Capítulo 3, seção 3.4, páginas 99–100 do PDF fornecido. Contexto: Java SE 8. Questão original de estudo; não é questão oficial do CP-T.', false, false),
('790ab777-9b6f-5826-9609-a6491ea58e53', NULL, 'bibliography', 'Informática', 'CP-T', 12, 'Linguagem de Programação', 'Fácil', 'Qual operador é normalmente usado para criar uma instância?', '["package.","extends.","new.","return.","import."]'::jsonb, 2, 'new inicia a criação e a chamada do construtor pertinente.', 'DEITEL, Paul; DEITEL, Harvey. Java: como programar. Tradução da 10ª edição norte-americana. Pearson Education do Brasil, 2017. Capítulo 3, seção 3.4, páginas 99–100 do PDF fornecido. Contexto: Java SE 8. Questão original de estudo; não é questão oficial do CP-T.', false, false),
('97e581cb-4c06-5d26-a8fd-46337d3b04ca', NULL, 'bibliography', 'Informática', 'CP-T', 13, 'Linguagem de Programação', 'Fácil', 'Em `this.nome = nome`, this.nome identifica:', '["Sempre o parâmetro.","Uma variável de outra classe.","O nome do pacote.","Um campo estático obrigatório.","O campo do objeto atual."]'::jsonb, 4, 'this resolve o sombreamento pelo parâmetro de mesmo nome.', 'DEITEL, Paul; DEITEL, Harvey. Java: como programar. Tradução da 10ª edição norte-americana. Pearson Education do Brasil, 2017. Capítulo 3, seção 3.4, páginas 99–100 do PDF fornecido. Contexto: Java SE 8. Questão original de estudo; não é questão oficial do CP-T.', false, false),
('7ddbaebd-142b-5840-8caa-846f55beccab', NULL, 'bibliography', 'Informática', 'CP-T', 14, 'Linguagem de Programação', 'Fácil', 'A principal responsabilidade de um construtor é:', '["Destruir outra instância.","Importar classes.","Inicializar o novo objeto.","Retornar obrigatoriamente um int.","Executar toda consulta do programa."]'::jsonb, 2, 'A inicialização pode também validar argumentos.', 'DEITEL, Paul; DEITEL, Harvey. Java: como programar. Tradução da 10ª edição norte-americana. Pearson Education do Brasil, 2017. Capítulo 3, seção 3.4, páginas 99–100 do PDF fornecido. Contexto: Java SE 8. Questão original de estudo; não é questão oficial do CP-T.', false, false),
('e7eb9c39-bd4c-5449-84fb-dc57ccca89a6', NULL, 'bibliography', 'Informática', 'CP-T', 15, 'Linguagem de Programação', 'Fácil', 'Para `double saldo=2.5; saldo+=1.25;`, o novo saldo é:', '["Erro de compilação.","4.0.","2.5.","3.75.","1.25."]'::jsonb, 3, 'A atribuição composta acrescenta o valor ao estado atual.', 'DEITEL, Paul; DEITEL, Harvey. Java: como programar. Tradução da 10ª edição norte-americana. Pearson Education do Brasil, 2017. Capítulo 3, seção 3.5, páginas 101–104 do PDF fornecido. Contexto: Java SE 8. Questão original de estudo; não é questão oficial do CP-T.', false, false),
('b58624f7-edb2-5644-adae-ff35a7fbc199', NULL, 'bibliography', 'Informática', 'CP-T', 16, 'Linguagem de Programação', 'Fácil', 'É adequado validar um depósito antes de alterar saldo?', '["Sim, mas apenas após apagar o saldo.","Não, setters não podem conter if.","Sim, para rejeitar valores incompatíveis com a regra do objeto.","Não, doubles não podem ser comparados.","Não, construtores substituem toda validação futura."]'::jsonb, 2, 'Regras de negócio precisam valer também nas atualizações.', 'DEITEL, Paul; DEITEL, Harvey. Java: como programar. Tradução da 10ª edição norte-americana. Pearson Education do Brasil, 2017. Capítulo 3, seção 3.5, páginas 101–104 do PDF fornecido. Contexto: Java SE 8. Questão original de estudo; não é questão oficial do CP-T.', false, false),
('0c5fc315-d1de-5da4-8544-5ab97e466521', NULL, 'bibliography', 'Informática', 'CP-T', 17, 'Linguagem de Programação', 'Fácil', 'Uma referência null usada para chamar método de instância causa normalmente:', '["NullPointerException.","Criação automática do objeto.","Erro de sintaxe obrigatório.","Retorno automático de zero.","Conversão em String vazia."]'::jsonb, 0, 'É necessário haver um objeto para a chamada de instância.', 'DEITEL, Paul; DEITEL, Harvey. Java: como programar. Tradução da 10ª edição norte-americana. Pearson Education do Brasil, 2017. Capítulo 3, seção 3.3, páginas 99–100 do PDF fornecido. Contexto: Java SE 8. Questão original de estudo; não é questão oficial do CP-T.', false, false),
('71e294a3-0bce-57eb-997e-147be956e000', NULL, 'bibliography', 'Informática', 'CP-T', 18, 'Linguagem de Programação', 'Fácil', 'Um método void pode usar `return;` para:', '["Alterar sua assinatura.","Converter-se em construtor.","Retornar um int implicitamente.","Criar o objeto atual.","Encerrar sua execução sem devolver valor."]'::jsonb, 4, 'O retorno sem expressão é compatível com void.', 'DEITEL, Paul; DEITEL, Harvey. Java: como programar. Tradução da 10ª edição norte-americana. Pearson Education do Brasil, 2017. Capítulo 3, seção 3.2, páginas 91–98 do PDF fornecido. Contexto: Java SE 8. Questão original de estudo; não é questão oficial do CP-T.', false, false),
('d27f85a4-cdbc-5d9c-a162-970ae8b6137d', NULL, 'bibliography', 'Informática', 'CP-T', 19, 'Linguagem de Programação', 'Fácil', 'O que JOptionPane.showInputDialog retorna ao receber texto normalmente?', '["double sempre.","int sempre.","JFrame.","Scanner.","String."]'::jsonb, 4, 'A entrada textual precisa de conversão explícita se for usada como número.', 'DEITEL, Paul; DEITEL, Harvey. Java: como programar. Tradução da 10ª edição norte-americana. Pearson Education do Brasil, 2017. Capítulo 3, seção 3.6, páginas 105–107 do PDF fornecido. Contexto: Java SE 8. Questão original de estudo; não é questão oficial do CP-T.', false, false),
('058b904d-7211-5801-81cb-b05197321dcf', NULL, 'bibliography', 'Informática', 'CP-T', 20, 'Linguagem de Programação', 'Fácil', 'String.format difere de printf porque:', '["Só aceita inteiros.","Retorna a string formatada.","Sempre imprime no terminal.","Retorna um Scanner.","Cria uma janela obrigatoriamente."]'::jsonb, 1, 'Formatar um valor não exige enviá-lo imediatamente à saída.', 'DEITEL, Paul; DEITEL, Harvey. Java: como programar. Tradução da 10ª edição norte-americana. Pearson Education do Brasil, 2017. Capítulo 3, seção 3.6, páginas 105–107 do PDF fornecido. Contexto: Java SE 8. Questão original de estudo; não é questão oficial do CP-T.', false, false)
ON CONFLICT (id) DO NOTHING;

COMMIT;
